# Compute count of column 'Gold' grouped by 'Winning manager'
print(f"🔧 Computing count of 'Gold' grouped by 'Winning manager'")

# Check if columns exist and operation is valid
if 'Gold' not in df.columns:
    print(f"❌ Error: Column 'Gold' not found")
    print(f"Available columns: {df.columns.tolist()}")
elif 'Winning manager' not in df.columns:
    print(f"❌ Error: Group by column 'Winning manager' not found")
    print(f"Available columns: {df.columns.tolist()}")
elif "count" not in ['count', 'sum', 'avg', 'min', 'max']:
    print(f"❌ Error: Invalid operation 'count'. Valid operations: ['count', 'sum', 'avg', 'min', 'max']")
else:
    try:
        if "count" == "count":
            result = df.groupby('Winning manager')['Gold'].count()
        elif "count" == "sum":
            result = df.groupby('Winning manager')['Gold'].sum()
        elif "count" == "avg":
            result = df.groupby('Winning manager')['Gold'].mean()
        elif "count" == "min":
            result = df.groupby('Winning manager')['Gold'].min()
        elif "count" == "max":
            result = df.groupby('Winning manager')['Gold'].max()

        print(f"✅ Count of 'Gold' by 'Winning manager':")
        print(result)

        # Convert to dataframe for consistency
        result_df = result.reset_index()
        result_df.columns = ['Winning manager', f'count_result']
        print(f"\n🔍 Result as table:")
        print(result_df)

    except Exception as e:
        print(f"❌ Error computing grouped count: {e}")
        print(f"Column dtypes: {df[['Gold', 'Winning manager']].dtypes}")
